	// Brake
	const csp300_BrakeValue = Math.round((csp300_brake_propertySelect() / 100) * (csp300_ledLength / 2));
	const csp300_brakeArray = Array(Math.floor(csp300_ledLength / 2)).fill($prop('ConspitLEDs.BrakeColour') ?? '#FFFF0000', 0, csp300_BrakeValue).reverse();

