	const csp300_throttleArray = Array(Math.floor(csp300_ledLength / 2)).fill($prop('ConspitLEDs.ThrottleColour') ?? '#FF00FF00', 0, csp300_ThrottleValue);

	return csp300_ledLength % 2 != 0
    	? csp300_brakeArray.concat(['#FFFFFFFF'], csp300_throttleArray)
    	: csp300_brakeArray.concat(csp300_throttleArray);
}
