if ($prop('ConspitLEDs.Clutch') ?? false) {
	UpdateGlobalColours.update();
	const { csp300_Clutch_Hex } = UpdateGlobalColours;
	const csp300_ClutchValue = Math.round(($prop('Clutch') / 100) * csp300_ledLength);

	return Array(csp300_ledLength).fill(csp300_Clutch_Hex, 0, csp300_ClutchValue);
}
return [null];

const currentBrakeType = $prop('ConspitLEDs.BrakeType');

if (currentBrakeType >= 2 && currentBrakeType <= 5) {

	UpdateGlobalColours.update();
	const { csp300_Brake_Hex } = UpdateGlobalColours;

	const currentBrakePressure = csp300_brake_propertySelect();
	const ledsLit = Math.min(
		csp300_brakeLedLength,
		Math.ceil((currentBrakePressure / 100) * csp300_brakeLedLength));

	const halfLedsLit = ledsLit / 2;
	const halfLength = csp300_brakeLedLength / 2;

	let needsBlinking = false;
	let blinkOutput = null;
	let blinkThresholdLedCount = 0;
	let blinkThresholdLedCountHalf = 0;

	const csp300_BrakeForceBlink = $prop('ConspitLEDs.BrakeForceBlink') ?? 80;
	const csp300_BrakeForceBlink2 = $prop('ConspitLEDs.BrakeForceBlink2') ?? 100;
	const blinkThresholdPercent = csp300_BrakeForceBlink / 100;

	if (currentBrakePressure >= csp300_BrakeForceBlink && ledsLit > 0) {
		blinkThresholdLedCount = Math.floor(blinkThresholdPercent * csp300_brakeLedLength);
		blinkThresholdLedCountHalf = Math.floor(blinkThresholdPercent * halfLength);
		
		// Fix 100% blink threshold
		if (csp300_BrakeForceBlink == 100 && csp300_brakeLedLength > 0) {
			blinkThresholdLedCount = csp300_brakeLedLength - 1;
			blinkThresholdLedCountHalf = Math.ceil(halfLength) - 1;
		}

		needsBlinking = currentBrakePressure >= csp300_BrakeForceBlink;
		if (needsBlinking) {
			const blinkFreqSelect = currentBrakePressure >= csp300_BrakeForceBlink2
				? 75
				: 150;
			blinkOutput = Math.floor(Date.now() / blinkFreqSelect) % 2 == 0
				? csp300_Brake_Hex
				: null;
		}
	}
	const BrakeArray = new Array(csp300_brakeLedLength).fill(null);
	const applyBlink = (index) => {
		if (BrakeArray[index] !== null) BrakeArray[index] = blinkOutput;
	};

	switch (currentBrakeType) {
		case 2: // Left to Right
			for (let i = 0; i < ledsLit; i++) {
				BrakeArray[i] = csp300_Brake_Hex;
				if (needsBlinking && i >= blinkThresholdLedCount) applyBlink(i);
			}
			break;

		case 3: // Right to Left 
			for (let i = 0; i < ledsLit; i++) {
				const pos = csp300_brakeLedLength - 1 - i;
				BrakeArray[pos] = csp300_Brake_Hex;
				if (needsBlinking && i >= blinkThresholdLedCount) applyBlink(pos);
			}
			break;

		case 4: // Meet in Middle 
			const ledsPerSide = Math.ceil(halfLedsLit);

			for (let i = 0; i < ledsPerSide; i++) {
				if (i >= halfLength) break;

				// Left side
				BrakeArray[i] = csp300_Brake_Hex;
				if (needsBlinking && i >= blinkThresholdLedCountHalf) applyBlink(i);

				// Right side
				const rightPos = csp300_brakeLedLength - 1 - i;

				BrakeArray[rightPos] = csp300_Brake_Hex;
				if (needsBlinking && i >= blinkThresholdLedCountHalf) applyBlink(rightPos);
			}
			break;

		case 5: // In to Out
			const centerPos = (csp300_brakeLedLength - 1) / 2;
			const isEven = csp300_brakeLedLength % 2 == 0;

			for (let i = 0; i < csp300_brakeLedLength; i++) {
				const distance = isEven 
					? Math.abs(i - (halfLength - 0.5))
					: Math.abs(i - centerPos);

				if (distance < halfLedsLit) {
					BrakeArray[i] = csp300_Brake_Hex;
					if (needsBlinking && distance >= blinkThresholdLedCountHalf) applyBlink(i);
				}
			}
			break;
		}
	return BrakeArray;
}
return [null];

